-- Упражнения книги 19, глава 11 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'virt-sim-net-bond', 0, 'lab', 'Доска сети: bond, потеря сетевой карты, VLAN на bond', 'Серверные сетевые карты, кабели в коммутатор, bond над ними и VLAN поверх. Доска показывает, у каких интерфейсов есть связь, и проверяет, что сервер остаётся на связи после потери любой карты. Шесть сценариев: собрать bond из двух карт, добавить вторую карту в bond с одним участником, поставить VLAN-интерфейс на bond для транкового порта, найти карту, которая выключена, переключить кабели при LACP на один коммутатор и поставить bond под мост для виртуальных машин. Упражнение решено, когда решены все сценарии.', '', 'Адрес принадлежит bond, а не его участникам. Участник bond, у которого нет связи, не защищает от потери соседа. Режим 802.3ad требует, чтобы все участники были подключены к одному коммутатору; режим active-backup этого не требует.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-bond-status', 1, 'func', 'Диагноз бонда по /proc', 'Напишите функцию bond_status(text): text — содержимое файла /proc/net/bonding/bondN. Верните словарь с ключами: mode — короткое имя режима по строке Bonding Mode (load balancing (round-robin) → balance-rr; fault-tolerance (active-backup) → active-backup, после названия возможен суффикс (fail_over_mac ...), его надо отбросить; load balancing (xor) → balance-xor; fault-tolerance (broadcast) → broadcast; IEEE 802.3ad Dynamic link aggregation → 802.3ad; transmit load balancing → balance-tlb; adaptive load balancing → balance-alb; иначе пустая строка); active — имя из строки Currently Active Slave, а если строки нет или там None, то пустая строка; down — список ведомых, у которых строка MII Status внутри их блока (блок начинается строкой Slave Interface) не равна up, то есть down, going down и going back тоже считаются неисправными, в порядке файла; flapping — список ведомых со значением Link Failure Count больше нуля, в порядке файла. Строки MII Status до первого блока ведомого относятся к самому бонду и не учитываются. Пустой текст даёт mode и active пустыми строками и пустые списки.', 'def bond_status(text):
    pass
', 'Идите по строкам, запоминайте текущее имя ведомого после Slave Interface и делите строку по первому двоеточию.', '{"func": "bond_status", "tests": [{"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: fault-tolerance (active-backup)\nPrimary Slave: None\nCurrently Active Slave: eth0\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 200\nPeer Notification Delay (ms): 0\n\nSlave Interface: eth0\nMII Status: up\nSpeed: 1000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 1000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\n"], "expected": {"mode": "active-backup", "active": "eth0", "down": [], "flapping": []}}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: fault-tolerance (active-backup)\nPrimary Slave: eth0 (primary_reselect always)\nCurrently Active Slave: eth1\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 200\nPeer Notification Delay (ms): 0\n\nSlave Interface: eth0\nMII Status: down\nSpeed: Unknown\nDuplex: Unknown\nLink Failure Count: 2\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 1000 Mbps\nDuplex: full\nLink Failure Count: 1\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\n"], "expected": {"mode": "active-backup", "active": "eth1", "down": ["eth0"], "flapping": ["eth0", "eth1"]}}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: load balancing (xor)\nTransmit Hash Policy: layer2+3 (2)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 300\nPeer Notification Delay (ms): 0\n\nSlave Interface: ens3f0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 3c:fd:fe:10:00:01\nSlave queue ID: 0\n\nSlave Interface: ens3f1\nMII Status: going down\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 4\nPermanent HW addr: 3c:fd:fe:10:00:02\nSlave queue ID: 0\n\nSlave Interface: ens3f2\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 7\nPermanent HW addr: 3c:fd:fe:10:00:03\nSlave queue ID: 0\n"], "expected": {"mode": "balance-xor", "active": "", "down": ["ens3f1"], "flapping": ["ens3f1", "ens3f2"]}}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: fault-tolerance (active-backup) (fail_over_mac active)\nPrimary Slave: None\nCurrently Active Slave: None\nMII Status: down\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\nSlave Interface: eno1\nMII Status: down\nSpeed: Unknown\nDuplex: Unknown\nLink Failure Count: 5\nPermanent HW addr: d0:94:66:00:00:01\nSlave queue ID: 0\n\nSlave Interface: eno2\nMII Status: going back\nSpeed: Unknown\nDuplex: Unknown\nLink Failure Count: 5\nPermanent HW addr: d0:94:66:00:00:02\nSlave queue ID: 0\n"], "expected": {"mode": "active-backup", "active": "", "down": ["eno1", "eno2"], "flapping": ["eno1", "eno2"]}}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: adaptive load balancing\nPrimary Slave: eth2 (primary_reselect always)\nCurrently Active Slave: eth2\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\nSlave Interface: eth2\nMII Status: up\nSpeed: 1000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 00:25:90:00:00:01\nSlave queue ID: 0\n\nSlave Interface: eth3\nMII Status: up\nSpeed: 1000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 00:25:90:00:00:02\nSlave queue ID: 0\n\nSlave Interface: eth4\nMII Status: up\nSpeed: 1000 Mbps\nDuplex: full\nLink Failure Count: 3\nPermanent HW addr: 00:25:90:00:00:03\nSlave queue ID: 0\n"], "expected": {"mode": "balance-alb", "active": "eth2", "down": [], "flapping": ["eth4"]}}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: fault-tolerance (broadcast)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\nSlave Interface: eth0\nMII Status: down\nSpeed: Unknown\nDuplex: Unknown\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:bb:00:01\nSlave queue ID: 0\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 1000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:bb:00:02\nSlave queue ID: 0\n"], "expected": {"mode": "broadcast", "active": "", "down": ["eth0"], "flapping": []}}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: IEEE 802.3ad Dynamic link aggregation\nTransmit Hash Policy: layer3+4 (1)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\n802.3ad info\nLACP active: on\nLACP rate: fast\nMin links: 0\nAggregator selection policy (ad_select): stable\nSystem priority: 65535\nSystem MAC address: 52:54:00:aa:00:10\nActive Aggregator Info:\n\tAggregator ID: 1\n\tNumber of ports: 2\n\tActor Key: 9\n\tPartner Key: 32768\n\tPartner Mac Address: 00:1c:73:12:34:56\n\nSlave Interface: eth0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 1\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 17\n    port state: 61\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 2\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 18\n    port state: 61\n"], "expected": {"mode": "802.3ad", "active": "", "down": [], "flapping": []}}, {"args": [""], "expected": {"mode": "", "active": "", "down": [], "flapping": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-tx-slave', 2, 'func', 'Какой интерфейс понесёт поток', 'Напишите функцию tx_slave(policy, n, flow): по документации ядра (модель, без учёта порядка байт реального процессора) вернуть номер ведомого интерфейса от 0 до n-1. flow — словарь с ключами smac и dmac (строки вида "52:54:00:aa:bb:01"), eth (число, тип протокола, 2048 для IPv4, 2054 для ARP), sip и dip (строки IPv4 или None, если пакет не IP), sport и dport (числа или None) и frag (True, если IP-фрагмент). Пусть mac5(m) — последний байт MAC-адреса как число, ip(a) — IPv4 как 32-битное число (a.b.c.d = a·2^24 + b·2^16 + c·2^8 + d). layer2: h = mac5(smac) xor mac5(dmac) xor eth. layer2+3: h начинается как в layer2, затем h = h xor ip(sip) xor ip(dip); layer3+4: h = (sport·65536 + dport) xor ip(sip) xor ip(dip), причём порты считаются нулём, если frag равен True или sport или dport равны None. Для layer2+3 и layer3+4 после этого выполняются h = h xor (h >> 16), h = h xor (h >> 8) (всё в 32 битах), а для layer3+4 ещё h = h >> 1. Ответ — h mod n. Если sip равен None (не IP), layer2+3 и layer3+4 считаются как layer2. Названия политик: "layer2", "layer2+3", "layer3+4".', 'def tx_slave(policy, n, flow):
    pass
', 'Напишите две вспомогательные функции: mac5 и ip; общий хвост (сдвиги на 16 и на 8) одинаков для двух политик.', '{"func": "tx_slave", "tests": [{"args": ["layer2", 2, {"smac": "52:54:00:aa:bb:01", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "10.0.0.5", "dip": "10.0.0.9", "sport": 40000, "dport": 443, "frag": false}], "expected": 1}, {"args": ["layer2", 2, {"smac": "52:54:00:aa:bb:01", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "10.0.0.5", "dip": "10.0.0.77", "sport": 40002, "dport": 80, "frag": false}], "expected": 1}, {"args": ["layer2", 4, {"smac": "52:54:00:aa:bb:10", "dmac": "52:54:00:cc:dd:fe", "eth": 2048, "sip": "10.0.0.5", "dip": "192.168.1.1", "sport": 40001, "dport": 22, "frag": false}], "expected": 2}, {"args": ["layer2+3", 2, {"smac": "52:54:00:aa:bb:01", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "10.0.0.5", "dip": "10.0.0.9", "sport": 40000, "dport": 443, "frag": false}], "expected": 1}, {"args": ["layer2+3", 3, {"smac": "52:54:00:aa:bb:07", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "172.16.4.20", "dip": "172.16.9.77", "sport": null, "dport": null, "frag": false}], "expected": 1}, {"args": ["layer3+4", 2, {"smac": "52:54:00:aa:bb:01", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "10.0.0.5", "dip": "10.0.0.9", "sport": 40000, "dport": 443, "frag": false}], "expected": 1}, {"args": ["layer3+4", 2, {"smac": "52:54:00:aa:bb:01", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "10.0.0.5", "dip": "10.0.0.9", "sport": 40002, "dport": 443, "frag": false}], "expected": 0}, {"args": ["layer3+4", 4, {"smac": "52:54:00:aa:bb:01", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "10.0.0.5", "dip": "10.0.0.9", "sport": 40004, "dport": 443, "frag": false}], "expected": 3}, {"args": ["layer3+4", 4, {"smac": "52:54:00:aa:bb:01", "dmac": "52:54:00:cc:dd:02", "eth": 2048, "sip": "10.0.0.5", "dip": "10.0.0.9", "sport": 40004, "dport": 443, "frag": true}], "expected": 2}, {"args": ["layer3+4", 3, {"smac": "52:54:00:aa:bb:01", "dmac": "ff:ff:ff:ff:ff:ff", "eth": 2054, "sip": null, "dip": null, "sport": null, "dport": null, "frag": false}], "expected": 1}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-detect-time', 3, 'func', 'Когда бонд объявит отказ', 'Драйвер опрашивает несущую в моменты miimon, 2·miimon, 3·miimon, ... миллисекунд. Напишите функцию down_time(miimon, downdelay, fail_at): несущая пропала в момент fail_at (мс) и больше не возвращается. Опрос, время которого не меньше fail_at, видит потерю (если потеря точно в момент опроса, опрос её видит). Ведомый переходит в состояние down через downdelay после обнаружения, но задержка считается в целых периодах опроса, то есть округляется вниз до кратного miimon. Верните момент в миллисекундах, когда ведомый станет down. Если miimon равен 0 (опрос выключен), верните -1.', 'def down_time(miimon, downdelay, fail_at):
    pass
', 'Первый опрос: потолок fail_at/miimon, но не меньше первого периода; к нему прибавьте (downdelay // miimon) * miimon.', '{"func": "down_time", "tests": [{"args": [100, 0, 250], "expected": 300}, {"args": [100, 200, 250], "expected": 500}, {"args": [100, 250, 300], "expected": 500}, {"args": [100, 99, 0], "expected": 100}, {"args": [50, 500, 1], "expected": 550}, {"args": [0, 200, 100], "expected": -1}, {"args": [100, 300, 301], "expected": 700}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-active-history', 4, 'func', 'Кто активен после каждого опроса', 'Смоделируйте active-backup с MII-мониторингом. Напишите функцию active_history(miimon, updelay, downdelay, initial, carrier): carrier — список пар [имя, список булевых] в порядке подключения, i-й элемент списка — есть ли несущая у этого интерфейса при i-м опросе (все списки одной длины). До первого опроса все интерфейсы в состоянии up, активен initial. Задержки в миллисекундах переводятся в опросы делением нацело на miimon: d = downdelay // miimon, u = updelay // miimon. Каждый опрос для каждого интерфейса по состоянию. up: несущая есть — остаётся up; несущей нет — задержка = d, дальше как в going down в том же опросе. going down: несущая есть — снова up; иначе если задержка <= 0 — down, иначе задержка уменьшается на 1 (и остаётся going down). down: несущей нет — остаётся down; есть — задержка = u, дальше как в going back в том же опросе. going back: несущей нет — снова down; иначе если задержка <= 0 — up, иначе задержка уменьшается на 1. После обработки всех интерфейсов выбор активного: пока активный интерфейс в состоянии up или going down, он остаётся; иначе активным становится первый по порядку интерфейс в состоянии up, а если такого нет — никто (пустая строка). Если в начале опроса активного интерфейса нет (пустая строка), то первый по порядку интерфейс, который в этом опросе оказывается в состоянии going back, сразу становится up без ожидания задержки (это правило срабатывает не более чем для одного интерфейса за опрос). Вернувшийся интерфейс активность не отбирает. Верните список имён активных после каждого опроса.', 'def active_history(miimon, updelay, downdelay, initial, carrier):
    pass
', 'Храните для каждого интерфейса пару (состояние, задержка); сначала обновите все интерфейсы, потом выбирайте активный.', '{"func": "active_history", "tests": [{"args": [100, 0, 0, "eth0", [["eth0", [true, true, false, false, true, true]], ["eth1", [true, true, true, true, true, true]]]], "expected": ["eth0", "eth0", "eth1", "eth1", "eth1", "eth1"]}, {"args": [100, 0, 200, "eth0", [["eth0", [true, true, false, false, false, false, true]], ["eth1", [true, true, true, true, true, true, true]]]], "expected": ["eth0", "eth0", "eth0", "eth0", "eth1", "eth1", "eth1"]}, {"args": [100, 0, 200, "eth0", [["eth0", [true, false, true, true, true]], ["eth1", [true, true, true, true, true]]]], "expected": ["eth0", "eth0", "eth0", "eth0", "eth0"]}, {"args": [100, 300, 0, "eth0", [["eth0", [false, false, false, false, true, true, true]], ["eth1", [true, true, false, false, false, true, true]]]], "expected": ["eth1", "eth1", "", "", "eth0", "eth0", "eth0"]}, {"args": [100, 200, 100, "eth1", [["eth0", [true, true, true, true, true]], ["eth1", [true, false, false, false, true]]]], "expected": ["eth1", "eth1", "eth0", "eth0", "eth0"]}, {"args": [100, 100, 0, "a", [["a", [true, false, true, true, true, true]], ["b", [false, false, false, true, true, true]]]], "expected": ["a", "", "a", "a", "a", "a"]}, {"args": [100, 0, 0, "a", [["a", []], ["b", []]]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-lacp-verdicts', 5, 'func', 'Вердикты по портам LACP', 'Напишите функцию lacp_verdicts(text): text — содержимое /proc/net/bonding/bondN для режима 802.3ad. Номер активного агрегата — строка Aggregator ID с отступом в разделе Active Aggregator Info (если вместо раздела стоит строка has no active aggregator, активного агрегата нет). В блоке каждого ведомого (он начинается строкой Slave Interface) есть MII Status, строка Aggregator ID без отступа (значение может быть N/A), а в секции details actor lacp pdu и details partner lacp pdu — строки system mac address и port state (число). Верните список пар (имя, вердикт) в порядке файла. Вердикт — первый подходящий из: link-down (MII Status не равен up); no-partner (system mac address партнёра равен 00:00:00:00:00:00); other-aggregator (Aggregator ID ведомого не равен номеру активного агрегата, в том числе N/A или нет активного агрегата); not-distributing (в port state актора не выставлены оба бита collecting 16 и distributing 32); ok.', 'def lacp_verdicts(text):
    pass
', 'Следите за секцией: до первого Slave Interface вы в шапке, внутри блока запоминайте, в actor или partner находитесь.', '{"func": "lacp_verdicts", "tests": [{"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: IEEE 802.3ad Dynamic link aggregation\nTransmit Hash Policy: layer3+4 (1)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\n802.3ad info\nLACP active: on\nLACP rate: fast\nMin links: 0\nAggregator selection policy (ad_select): stable\nSystem priority: 65535\nSystem MAC address: 52:54:00:aa:00:10\nActive Aggregator Info:\n\tAggregator ID: 1\n\tNumber of ports: 2\n\tActor Key: 9\n\tPartner Key: 32768\n\tPartner Mac Address: 00:1c:73:12:34:56\n\nSlave Interface: eth0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 1\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 17\n    port state: 61\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 2\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 18\n    port state: 61\n"], "expected": [{"__tuple__": ["eth0", "ok"]}, {"__tuple__": ["eth1", "ok"]}]}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: IEEE 802.3ad Dynamic link aggregation\nTransmit Hash Policy: layer3+4 (1)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\n802.3ad info\nLACP active: on\nLACP rate: fast\nMin links: 0\nAggregator selection policy (ad_select): stable\nSystem priority: 65535\nSystem MAC address: 52:54:00:aa:00:10\nActive Aggregator Info:\n\tAggregator ID: 1\n\tNumber of ports: 1\n\tActor Key: 9\n\tPartner Key: 32768\n\tPartner Mac Address: 00:1c:73:12:34:56\n\nSlave Interface: eth0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 1\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 17\n    port state: 61\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\nAggregator ID: 2\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 2\n    port state: 69\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:00:00:00:00:00\n    oper key: 32768\n    port priority: 32768\n    port number: 18\n    port state: 1\n"], "expected": [{"__tuple__": ["eth0", "ok"]}, {"__tuple__": ["eth1", "no-partner"]}]}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: IEEE 802.3ad Dynamic link aggregation\nTransmit Hash Policy: layer3+4 (1)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\n802.3ad info\nLACP active: on\nLACP rate: fast\nMin links: 0\nAggregator selection policy (ad_select): stable\nSystem priority: 65535\nSystem MAC address: 52:54:00:aa:00:10\nActive Aggregator Info:\n\tAggregator ID: 1\n\tNumber of ports: 1\n\tActor Key: 9\n\tPartner Key: 32768\n\tPartner Mac Address: 00:1c:73:12:34:56\n\nSlave Interface: eth0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 1\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 17\n    port state: 61\n\nSlave Interface: eth1\nMII Status: down\nSpeed: Unknown\nDuplex: full\nLink Failure Count: 3\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\nAggregator ID: 2\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 2\n    port state: 69\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:00:00:00:00:00\n    oper key: 32768\n    port priority: 32768\n    port number: 18\n    port state: 1\n"], "expected": [{"__tuple__": ["eth0", "ok"]}, {"__tuple__": ["eth1", "link-down"]}]}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: IEEE 802.3ad Dynamic link aggregation\nTransmit Hash Policy: layer3+4 (1)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\n802.3ad info\nLACP active: on\nLACP rate: fast\nMin links: 0\nAggregator selection policy (ad_select): stable\nSystem priority: 65535\nSystem MAC address: 52:54:00:aa:00:10\nActive Aggregator Info:\n\tAggregator ID: 1\n\tNumber of ports: 2\n\tActor Key: 9\n\tPartner Key: 32768\n\tPartner Mac Address: 00:1c:73:12:34:56\n\nSlave Interface: eth0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 1\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 17\n    port state: 61\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\nAggregator ID: 2\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 10\n    port priority: 255\n    port number: 2\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:99:99:99\n    oper key: 32768\n    port priority: 32768\n    port number: 18\n    port state: 61\n\nSlave Interface: eth2\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:03\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 3\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 19\n    port state: 61\n"], "expected": [{"__tuple__": ["eth0", "ok"]}, {"__tuple__": ["eth1", "other-aggregator"]}, {"__tuple__": ["eth2", "ok"]}]}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: IEEE 802.3ad Dynamic link aggregation\nTransmit Hash Policy: layer3+4 (1)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\n802.3ad info\nLACP active: on\nLACP rate: fast\nMin links: 0\nAggregator selection policy (ad_select): stable\nSystem priority: 65535\nSystem MAC address: 52:54:00:aa:00:10\nActive Aggregator Info:\n\tAggregator ID: 1\n\tNumber of ports: 2\n\tActor Key: 9\n\tPartner Key: 32768\n\tPartner Mac Address: 00:1c:73:12:34:56\n\nSlave Interface: ens1f0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 3c:fd:fe:20:00:01\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 1\n    port state: 61\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 17\n    port state: 61\n\nSlave Interface: ens1f1\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 3c:fd:fe:20:00:02\nSlave queue ID: 0\nAggregator ID: 1\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 2\n    port state: 13\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:1c:73:12:34:56\n    oper key: 32768\n    port priority: 32768\n    port number: 18\n    port state: 61\n"], "expected": [{"__tuple__": ["ens1f0", "ok"]}, {"__tuple__": ["ens1f1", "not-distributing"]}]}, {"args": ["Ethernet Channel Bonding Driver: v6.8.0-45-generic\n\nBonding Mode: IEEE 802.3ad Dynamic link aggregation\nTransmit Hash Policy: layer3+4 (1)\nMII Status: up\nMII Polling Interval (ms): 100\nUp Delay (ms): 0\nDown Delay (ms): 0\nPeer Notification Delay (ms): 0\n\n802.3ad info\nLACP active: on\nLACP rate: fast\nMin links: 0\nAggregator selection policy (ad_select): stable\nSystem priority: 65535\nSystem MAC address: 52:54:00:aa:00:10\nbond bond0 has no active aggregator\n\nSlave Interface: eth0\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:01\nSlave queue ID: 0\nAggregator ID: N/A\n\nSlave Interface: eth1\nMII Status: up\nSpeed: 10000 Mbps\nDuplex: full\nLink Failure Count: 0\nPermanent HW addr: 52:54:00:aa:00:02\nSlave queue ID: 0\nAggregator ID: 3\nActor Churn State: none\nPartner Churn State: none\nActor Churned Count: 0\nPartner Churned Count: 0\ndetails actor lacp pdu:\n    system priority: 65535\n    system mac address: 52:54:00:aa:00:10\n    port key: 9\n    port priority: 255\n    port number: 2\n    port state: 69\ndetails partner lacp pdu:\n    system priority: 32768\n    system mac address: 00:00:00:00:00:00\n    oper key: 32768\n    port priority: 32768\n    port number: 18\n    port state: 1\n"], "expected": [{"__tuple__": ["eth0", "other-aggregator"]}, {"__tuple__": ["eth1", "no-partner"]}]}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-mtu-payload', 6, 'func', 'Наибольший размер для ping -M do', 'Напишите функцию max_ping_payload(path_mtus, encaps): path_mtus — непустой список MTU звеньев сети под тоннелями (underlay), encaps — список инкапсуляций, через которые идёт трафик ВМ. Расходы на MTU: vlan — 0 (тег добавляется к кадру, а не к пакету), vxlan — 50 (underlay IPv4: 20 + 8 + 8 + 14), vxlan6 — 70 (underlay IPv6: 40 + 8 + 8 + 14), ipip — 20. MTU внутри тоннеля — это минимальный MTU звена минус сумма расходов всех инкапсуляций. Верните наибольшее значение ключа -s для команды ping -M do -s N по IPv4 внутри тоннеля: MTU минус 20 байт заголовка IPv4 и 8 байт заголовка ICMP, но не меньше нуля.', 'def max_ping_payload(path_mtus, encaps):
    pass
', 'min(path_mtus) - sum(cost[e] for e in encaps) - 28, и max с нулём.', '{"func": "max_ping_payload", "tests": [{"args": [[1500], []], "expected": 1472}, {"args": [[9000, 9000], ["vxlan"]], "expected": 8922}, {"args": [[1500, 9000], ["vlan", "vxlan"]], "expected": 1422}, {"args": [[1500], ["vxlan6"]], "expected": 1402}, {"args": [[9000, 1500, 9000], ["ipip"]], "expected": 1452}, {"args": [[40], ["vxlan"]], "expected": 0}, {"args": [[9000], ["vlan", "vlan"]], "expected": 8972}, {"args": [[1500], ["vxlan", "ipip"]], "expected": 1402}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-ping-df', 7, 'func', 'Чем кончится ping с запретом фрагментации', 'Напишите функцию ping_df(size, local_mtu, hops): size — значение ключа -s в ping -M do -s N (IPv4), длина пакета равна size + 28, local_mtu — MTU исходящего интерфейса, hops — список троек (имя, mtu_следующего_звена, шлёт_icmp) в порядке пути: маршрутизатор пересылает пакет на звено с этим MTU и, если пакет больше, а шлёт_icmp равно True, отвечает сообщением Frag needed с этим MTU, иначе молча отбрасывает пакет. Результат — кортеж: ("local", local_mtu), если пакет больше local_mtu (ping сообщает message too long и ничего не отправляет); ("frag-needed", имя, mtu) для первого по пути маршрутизатора, у которого звено меньше пакета и который шлёт ICMP; ("timeout", имя), если первый такой маршрутизатор молчит; иначе ("ok",). Маршрутизаторы после первого препятствия не рассматриваются.', 'def ping_df(size, local_mtu, hops):
    pass
', 'Длина = size + 28; сначала сравните с local_mtu, потом найдите первое звено, где mtu меньше длины.', '{"func": "ping_df", "tests": [{"args": [1472, 1500, [["r1", 1500, true], ["r2", 1500, true]]], "expected": {"__tuple__": ["ok"]}}, {"args": [1473, 1500, [["r1", 1500, true]]], "expected": {"__tuple__": ["local", 1500]}}, {"args": [1472, 1500, [["r1", 1500, true], ["r2", 1400, true], ["r3", 1300, true]]], "expected": {"__tuple__": ["frag-needed", "r2", 1400]}}, {"args": [1472, 1500, [["r1", 1400, false], ["r2", 1300, true]]], "expected": {"__tuple__": ["timeout", "r1"]}}, {"args": [8972, 9000, [["sw", 9000, true], ["gw", 1500, true]]], "expected": {"__tuple__": ["frag-needed", "gw", 1500]}}, {"args": [56, 1500, [["r1", 68, true]]], "expected": {"__tuple__": ["frag-needed", "r1", 68]}}, {"args": [40, 1500, [["r1", 68, true]]], "expected": {"__tuple__": ["ok"]}}, {"args": [1400, 1500, [["r1", 1428, true], ["r2", 1427, false]]], "expected": {"__tuple__": ["timeout", "r2"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-stats-delta', 8, 'func', 'Растущие счётчики ошибок', 'Напишите функцию error_deltas(before, after, seconds): before и after — два вывода ethtool -S (первая строка NIC statistics:, затем строки вида "     имя: число"), снятые с интервалом seconds секунд (целое, не меньше 1). Рассматриваются только счётчики, которые есть в обоих выводах и в имени которых (маленькими буквами) встречается одна из подстрок err, drop, discard, crc, missed, fifo, timeout. Для каждого берётся приращение after - before; счётчики с приращением 0 и счётчики, которые уменьшились (карту или драйвер перезагружали), пропускаются. Верните список троек (имя, приращение, приращение_в_секунду) с целым делением на seconds, отсортированный по приращению по убыванию, а при равенстве по имени.', 'def error_deltas(before, after, seconds):
    pass
', 'Разберите каждый вывод в словарь, пропустив первую строку; потом пересеките ключи и отфильтруйте по подстрокам.', '{"func": "error_deltas", "tests": [{"args": ["NIC statistics:\n     rx_packets: 9876543\n     tx_packets: 8765432\n     rx_bytes: 11223344556\n     tx_bytes: 9988776655\n     rx_errors: 0\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 4\n     rx_missed_errors: 1000\n     rx_fifo_errors: 0\n     tx_timeout_count: 0\n     rx_queue_0_packets: 5000000\n     rx_queue_0_drops: 10\n", "NIC statistics:\n     rx_packets: 9976543\n     tx_packets: 8865432\n     rx_bytes: 11323344556\n     tx_bytes: 10088776655\n     rx_errors: 12\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 12\n     rx_missed_errors: 1600\n     rx_fifo_errors: 0\n     tx_timeout_count: 1\n     rx_queue_0_packets: 5100000\n     rx_queue_0_drops: 40\n     rx_queue_1_drops: 5\n", 10], "expected": [{"__tuple__": ["rx_missed_errors", 600, 60]}, {"__tuple__": ["rx_queue_0_drops", 30, 3]}, {"__tuple__": ["rx_errors", 12, 1]}, {"__tuple__": ["rx_crc_errors", 8, 0]}, {"__tuple__": ["tx_timeout_count", 1, 0]}]}, {"args": ["NIC statistics:\n     rx_packets: 9876543\n     tx_packets: 8765432\n     rx_bytes: 11223344556\n     tx_bytes: 9988776655\n     rx_errors: 0\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 4\n     rx_missed_errors: 1000\n     rx_fifo_errors: 0\n     tx_timeout_count: 0\n     rx_queue_0_packets: 5000000\n     rx_queue_0_drops: 10\n", "NIC statistics:\n     rx_packets: 9976543\n     tx_packets: 8865432\n     rx_bytes: 11323344556\n     tx_bytes: 10088776655\n     rx_errors: 12\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 12\n     rx_missed_errors: 1600\n     rx_fifo_errors: 0\n     tx_timeout_count: 1\n     rx_queue_0_packets: 5100000\n     rx_queue_0_drops: 40\n     rx_queue_1_drops: 5\n", 60], "expected": [{"__tuple__": ["rx_missed_errors", 600, 10]}, {"__tuple__": ["rx_queue_0_drops", 30, 0]}, {"__tuple__": ["rx_errors", 12, 0]}, {"__tuple__": ["rx_crc_errors", 8, 0]}, {"__tuple__": ["tx_timeout_count", 1, 0]}]}, {"args": ["NIC statistics:\n     rx_packets: 9876543\n     tx_packets: 8765432\n     rx_bytes: 11223344556\n     tx_bytes: 9988776655\n     rx_errors: 0\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 4\n     rx_missed_errors: 1000\n     rx_fifo_errors: 0\n     tx_timeout_count: 0\n     rx_queue_0_packets: 5000000\n     rx_queue_0_drops: 10\n", "NIC statistics:\n     rx_packets: 100\n     tx_packets: 80\n     rx_errors: 0\n     rx_crc_errors: 0\n     rx_dropped: 3\n", 5], "expected": []}, {"args": ["NIC statistics:\n     rx_packets: 100\n     tx_packets: 80\n     rx_errors: 0\n     rx_crc_errors: 0\n     rx_dropped: 3\n", "NIC statistics:\n     rx_packets: 9876543\n     tx_packets: 8765432\n     rx_bytes: 11223344556\n     tx_bytes: 9988776655\n     rx_errors: 0\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 4\n     rx_missed_errors: 1000\n     rx_fifo_errors: 0\n     tx_timeout_count: 0\n     rx_queue_0_packets: 5000000\n     rx_queue_0_drops: 10\n", 1], "expected": [{"__tuple__": ["rx_dropped", 117, 117]}, {"__tuple__": ["rx_crc_errors", 4, 4]}]}, {"args": ["NIC statistics:\n     rx_packets: 9876543\n     tx_packets: 8765432\n     rx_bytes: 11223344556\n     tx_bytes: 9988776655\n     rx_errors: 0\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 4\n     rx_missed_errors: 1000\n     rx_fifo_errors: 0\n     tx_timeout_count: 0\n     rx_queue_0_packets: 5000000\n     rx_queue_0_drops: 10\n", "NIC statistics:\n     rx_packets: 9876543\n     tx_packets: 8765432\n     rx_bytes: 11223344556\n     tx_bytes: 9988776655\n     rx_errors: 0\n     tx_errors: 0\n     rx_dropped: 120\n     tx_dropped: 0\n     rx_crc_errors: 4\n     rx_missed_errors: 1000\n     rx_fifo_errors: 0\n     tx_timeout_count: 0\n     rx_queue_0_packets: 5000000\n     rx_queue_0_drops: 10\n", 30], "expected": []}, {"args": ["NIC statistics:\n", "NIC statistics:\n", 1], "expected": []}, {"args": ["NIC statistics:\n     rx_err_a: 1\n     rx_err_b: 1\n     Rx_Drop_Total: 0\n", "NIC statistics:\n     rx_err_a: 6\n     rx_err_b: 6\n     Rx_Drop_Total: 9\n     tx_err_new: 4\n", 2], "expected": [{"__tuple__": ["Rx_Drop_Total", 9, 4]}, {"__tuple__": ["rx_err_a", 5, 2]}, {"__tuple__": ["rx_err_b", 5, 2]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-offload-report', 9, 'func', 'Отчёт по разгрузкам ethtool -k', 'Напишите функцию offload_report(text): text — вывод ethtool -k. Первая строка (Features for ...:) пропускается; остальные строки (включая вложенные, с отступом табуляцией) имеют вид "имя: on" или "имя: off" с возможным суффиксом [fixed] (изменить нельзя), [requested on] или [requested off] (изменение запрошено, но не применено). Верните словарь с ключами: on — имена с активным значением on без суффиксов; off — имена с активным значением off без суффиксов; fixed — имена с суффиксом [fixed] (любое значение); pending — список пар (имя, запрошенное значение), где запрошенное значение берётся из суффикса, для строк с [requested on] или [requested off]. Во всех списках сохраняется порядок строк. Пустые строки пропускаются.', 'def offload_report(text):
    pass
', 'Отделите суффикс в квадратных скобках от значения: rsplit('' ['', 1) или проверка endswith.', '{"func": "offload_report", "tests": [{"args": ["Features for eth0:\nrx-checksumming: on\ntx-checksumming: on\n\ttx-checksum-ipv4: off [fixed]\n\ttx-checksum-ip-generic: on\n\ttx-checksum-ipv6: off [fixed]\nscatter-gather: on\n\ttx-scatter-gather: on\n\ttx-scatter-gather-fraglist: off [fixed]\ntcp-segmentation-offload: on\n\ttx-tcp-segmentation: on\n\ttx-tcp-ecn-segmentation: off [fixed]\n\ttx-tcp-mangleid-segmentation: off\ngeneric-segmentation-offload: on\ngeneric-receive-offload: off [requested on]\nlarge-receive-offload: off [fixed]\nrx-vlan-offload: on\ntx-vlan-offload: on [requested off]\nntuple-filters: off [fixed]\nreceive-hashing: on\nhighdma: on [fixed]\nrx-vlan-filter: on [fixed]\n"], "expected": {"on": ["rx-checksumming", "tx-checksumming", "tx-checksum-ip-generic", "scatter-gather", "tx-scatter-gather", "tcp-segmentation-offload", "tx-tcp-segmentation", "generic-segmentation-offload", "rx-vlan-offload", "receive-hashing"], "off": ["tx-tcp-mangleid-segmentation"], "fixed": ["tx-checksum-ipv4", "tx-checksum-ipv6", "tx-scatter-gather-fraglist", "tx-tcp-ecn-segmentation", "large-receive-offload", "ntuple-filters", "highdma", "rx-vlan-filter"], "pending": [{"__tuple__": ["generic-receive-offload", "on"]}, {"__tuple__": ["tx-vlan-offload", "off"]}]}}, {"args": ["Features for bond0:\nrx-checksumming: off [fixed]\ngeneric-receive-offload: on\ntx-vlan-offload: on\nvlan-challenged: off [fixed]\n"], "expected": {"on": ["generic-receive-offload", "tx-vlan-offload"], "off": [], "fixed": ["rx-checksumming", "vlan-challenged"], "pending": []}}, {"args": ["Features for lo:\n"], "expected": {"on": [], "off": [], "fixed": [], "pending": []}}, {"args": ["Features for eth1:\ntx-gso-robust: off [fixed]\n\nrx-gro-hw: off\n"], "expected": {"on": [], "off": ["rx-gro-hw"], "fixed": ["tx-gso-robust"], "pending": []}}, {"args": ["Features for eth1:\nrx-gro-list: on [requested off]\nhw-tc-offload: off [requested on]\n"], "expected": {"on": [], "off": [], "fixed": [], "pending": [{"__tuple__": ["rx-gro-list", "off"]}, {"__tuple__": ["hw-tc-offload", "on"]}]}}, {"args": [""], "expected": {"on": [], "off": [], "fixed": [], "pending": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 11, 'la11-choose-mode', 10, 'func', 'Выбор режима бонда', 'Напишите функцию choose_mode(need, switch, speeds, rx_balance), которая выбирает режим бонда по требованиям. need — одно из "failover" (нужна только отказоустойчивость), "throughput" (нужна суммарная пропускная способность многих потоков), "single_flow" (одно TCP-соединение должно быть быстрее одного интерфейса). switch — возможности коммутатора: "lacp" (порты можно собрать в LACP-канал), "static" (только статическая группа портов без LACP), "none" (настроить нельзя). speeds — список скоростей интерфейсов (пустой или с одним значением считается однородным), rx_balance — нужно ли балансировать и входящий трафик. Правила по порядку. single_flow: "balance-rr", если switch равен static, иначе "none" (строка). failover: "802.3ad", если switch равен lacp и все скорости равны, иначе "active-backup". throughput при switch lacp: "802.3ad", если все скорости равны, иначе "balance-tlb" (он допускает разные скорости и не требует настройки коммутатора); при static: "balance-xor"; при none: "balance-alb", если rx_balance равно True, иначе "balance-tlb".', 'def choose_mode(need, switch, speeds, rx_balance):
    pass
', 'Начните с uniform = len(set(speeds)) <= 1, затем разберите need по порядку.', '{"func": "choose_mode", "tests": [{"args": ["failover", "none", [1000, 1000], false], "expected": "active-backup"}, {"args": ["failover", "lacp", [10000, 10000], false], "expected": "802.3ad"}, {"args": ["failover", "lacp", [1000, 10000], false], "expected": "active-backup"}, {"args": ["throughput", "lacp", [10000, 10000, 10000], true], "expected": "802.3ad"}, {"args": ["throughput", "lacp", [1000, 10000], false], "expected": "balance-tlb"}, {"args": ["throughput", "static", [1000, 1000], true], "expected": "balance-xor"}, {"args": ["throughput", "none", [1000, 1000], true], "expected": "balance-alb"}, {"args": ["throughput", "none", [1000], false], "expected": "balance-tlb"}, {"args": ["single_flow", "static", [10000, 10000], false], "expected": "balance-rr"}, {"args": ["single_flow", "lacp", [10000, 10000], false], "expected": "none"}]}');
